mapper.select:
SELECT p.id, p.name, p.status, p.image_url, p.sort_order, p.created_at, COUNT(*) OVER() AS total_count FROM presets p
p.deleted_at IS NULL
AND p.status = #{status}
AND ( p.name ILIKE CONCAT('%', #{keyword}, '%') OR p.note ILIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.sort_order ASC, p.created_at DESC LIMIT #{limit} OFFSET #{offset}
